WITH CoefficientOfVariation AS ( SELECT ata.ACADEMIC_YEAR, ata.ACADEMIC_YEAR_DESC, STDDEV_SAMP(ccso.TOTAL_UNITS) / AVG(ccso.TOTAL_UNITS) AS coefficient_of_variation FROM COURSE_CATALOG_SUBJECT_OFFERED ccso JOIN ACADEMIC_TERMS_ALL ata ON ccso.TERM_CODE = ata.TERM_CODE WHERE ccso.DEPARTMENT_NAME = 'Mathematics' AND ccso.IS_OFFERED_FALL_TERM = 'Y' AND ccso.TOTAL_UNITS > 0 GROUP BY ata.ACADEMIC_YEAR, ata.ACADEMIC_YEAR_DESC ORDER BY ata.ACADEMIC_YEAR ), EnrolledStats AS ( SELECT ACADEMIC_TERMS.ACADEMIC_YEAR, MAX(TIP_SUBJECT_OFFERED.NUM_ENROLLED_STUDENTS) - MIN(TIP_SUBJECT_OFFERED.NUM_ENROLLED_STUDENTS) AS enrolled_range, VARIANCE(TIP_SUBJECT_OFFERED.NUM_ENROLLED_STUDENTS) AS enrolled_variance FROM COURSE_CATALOG_SUBJECT_OFFERED JOIN ACADEMIC_TERMS ON COURSE_CATALOG_SUBJECT_OFFERED.TERM_CODE = ACADEMIC_TERMS.TERM_CODE JOIN TIP_SUBJECT_OFFERED ON ACADEMIC_TERMS.TERM_CODE = TIP_SUBJECT_OFFERED.TERM_CODE WHERE COURSE_CATALOG_SUBJECT_OFFERED.IS_OFFERED_FALL_TERM = 'Y' AND TIP_SUBJECT_OFFERED.NUM_ENROLLED_STUDENTS > 0 AND COURSE_CATALOG_SUBJECT_OFFERED.DEPARTMENT_NAME = 'Mathematics' GROUP BY ACADEMIC_TERMS.ACADEMIC_YEAR ORDER BY enrolled_range DESC ) SELECT cov.ACADEMIC_YEAR, cov.ACADEMIC_YEAR_DESC, cov.coefficient_of_variation, es.enrolled_range, es.enrolled_variance FROM CoefficientOfVariation cov JOIN EnrolledStats es ON cov.ACADEMIC_YEAR = es.ACADEMIC_YEAR ORDER BY cov.ACADEMIC_YEAR;